def add(short,title,year,type,status,authors,attr,url,doi,summary,problem,method,methods,domains,codes,depth,note,sources=None,**extra):
 r={'title':title,'year':year,'type':type,'status':status,'authors':authors,'school_attribution':attr,'url':url,'doi':doi,'summary_vi':summary,'problem_vi':problem,'ai_method_vi':method,'ai_methods':methods,'application_domains':domains,'ai_topic_codes':codes,'reading_depth':depth,'verification_note':note,'source_urls':list(dict.fromkeys([url]+(sources or []))),'checked_on':'2026-10-30','full_text_read':False,**extra};schools[short]['items'].append(r);return r
def keep(short,index,problem,method,methods,domains,codes,status='published',depth='abstract_and_metadata',attr=None,note=None,**extra):
 i=lookup[short]['items'][index]
 r=add(short,i['title'],i['year'],i['type'],status,i.get('authors',([i['principal_investigator']] if i.get('principal_investigator') else [])),attr or i.get('university_attribution') or i['verification_note'],i['url'],i.get('doi'),i['summary_vi'],problem,method,methods,domains,codes,depth,note or i['verification_note'],i.get('source_urls',[]),origin='retained_and_reassessed',previous_record_id=i['record_id'],**extra)
 for k in ['project_id','published_date','period','status_as_reported','principal_investigator','collaborating_universities','catalogue_detail_url']:
  if k in i:r[k]=i[k]
 return r
